/**
 * Puerto de `ccnmt: packages/headless-sdk/src/agentSdkTypes.ts` (verbatim en
 * estructura; los imports que en la fuente son auto-referencias al propio
 * paquete por nombre, `@claude-code-how-works/headless-sdk/*`, se portan
 * como imports relativos — son módulos hermanos dentro del MISMO paquete,
 * no una dependencia cruzada. `@modelcontextprotocol/sdk` es un paquete npm
 * genuino, declarado como dependencia real de este paquete.)
 *
 * Main entrypoint for Claude Code Agent SDK types.
 *
 * This file re-exports the public SDK API from:
 * - sdk/coreTypes.ts - Common serializable types (messages, configs)
 * - sdk/runtimeTypes.ts - Non-serializable types (callbacks, interfaces)
 *
 * SDK builders who need control protocol types should import from
 * sdk/controlTypes.ts directly.
 */
import type { EXIT_REASONS, HOOK_EVENTS } from './coreTypes.js'

import type {
  CallToolResult,
  ToolAnnotations,
} from '@modelcontextprotocol/sdk/types.js'

// Control protocol types for SDK builders (bridge subpath consumers)
/** @alpha */
export type {
  SDKControlRequest,
  SDKControlResponse,
} from './controlTypes.ts'
// Re-export core types (common serializable types)
export * from './coreTypes.ts'
// Re-export runtime types (callbacks, interfaces with methods)
export * from './runtimeTypes.ts'

// Settings types (generated from settings JSON schema). Inlined from
// src/entrypoints/sdk/settingsTypes.generated.ts which was a 4-LOC stub.
export type Settings = Record<string, unknown>
// Re-export tool types (all marked @internal until SDK API stabilizes)
// V7-flipped: was `export * from '@thyrox/headless-sdk/agentSdkTypes.js'`. Inlined
// because toolTypes.ts was a 9-LOC stub with one type alias.
/** @internal */
export type SdkToolDefinition = {
  name: string
  description: string
  inputSchema: Record<string, unknown>
  [key: string]: unknown
}

// ============================================================================
// Functions
// ============================================================================

import type {
  SDKMessage,
  SDKResultMessage,
  SDKSessionInfo,
  SDKUserMessage,
} from './coreTypes.ts'
// Import types needed for function signatures
import type {
  AnyZodRawShape,
  ForkSessionOptions,
  ForkSessionResult,
  GetSessionInfoOptions,
  GetSessionMessagesOptions,
  InferShape,
  InternalOptions,
  InternalQuery,
